void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    struct ftrace_event_file *file;
    struct trace_entry *entry;
    struct ring_buffer *buffer;
    unsigned long flags;

    id = (long)get_syscall_number(current, regs);
    if (id < 0)
        return;

    file = find_event_file(data, sys_call_event);
    if (!file || !file->enabled)
        return;

    buffer = file->ring_buffer;
    if (!buffer)
        return;

    flags = raw_local_save_flags();
    preempt_disable_notrace();
    entry = __trace_buffer_lock_reserve(buffer, file, TRACE_SYSCALL_ENTRY, sizeof(*entry), flags);
    if (!entry)
        goto out;

    entry->type = TRACE_SYSCALL_ENTRY;
    entry->seq = ++file->entries;
    entry->id = id;
    entry->args[0] = regs->di;
    entry->args[1] = regs->si;
    entry->args[2] = regs->dx;
    entry->args[3] = regs->c; /* R10 in x86_64 */
    entry->args[4] = regs->r8;
    entry->args[5] = regs->r9;
    ring_buffer_commit(buffer, file, entry);
out:
    preempt_enable_notrace();
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id)
{
    int syscall_nr = regs->syscallno;

    if (syscall_nr < 0)
        return;

    struct ftrace_event_file *event_file = get_syscall_event_file(syscall_nr);
    if (!event_file || !event_file->enabled)
        return;

    struct trace_entry *entry;
    struct ring_buffer *buffer = event_file->buffer;
    unsigned long flags;
    int preemption = preempt_count();

    local_save_flags(flags);

    if (!ring_buffer_lock_reserve(buffer, sizeof(*entry)))
        return;

    entry = ring_buffer_peek_data(buffer);
    entry->type = TRACE_SYSCALL_ENTRY;
    entry->syscall_id = id;

    for (int i = 0; i < 6; i++)
        entry->args[i] = regs->regs[i];

    ring_buffer_commit_data(buffer);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    int syscall_num = regs->syscall;
    struct ftrace_event_file *file;

    file = find_event_file(current, id);
    if (!file || !file->enabled)
        return;

    struct ftrace_raw_event_syscall_enter *entry;
    struct ring_buffer_event *event;
    unsigned long flags, preemption;

    flags = arch_local_save_flags();
    preemption = preempt_count();

    event = ring_buffer_lock_reserve(file->ring_buffer, sizeof(*entry));
    if (!event)
        return;

    entry = ring_buffer_event_data(event);
    entry->nr = syscall_num;
    entry->args[0] = regs->regs[0];
    entry->args[1] = regs->regs[1];
    entry->args[2] = regs->regs[2];
    entry->args[3] = regs->regs[3];
    entry->args[4] = regs->regs[4];
    entry->args[5] = regs->regs[5];

    ring_buffer_unlock_commit(file->ring_buffer, event);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    int syscall_num = regs->orig_ax;
    struct ftrace_event_file *event_file;
    struct trace_entry *entry;
    unsigned long flags;
    int pc;

    if (syscall_num < 0 || syscall_num >= __NR_syscalls)
        return;

    event_file = get_syscall_event_file(syscall_num);
    if (!event_file || !event_file->enabled)
        return;

    flags = raw_local_save_flags();
    pc = preempt_count();

    entry = trace_find_next_entry();
    if (!entry)
        return;

    entry->type = TRACE_SYSCALL_ENTRY;
    entry->syscall_id = syscall_num;

    trace_copy_arguments(entry, regs, syscall_num);
    trace_peek_irq_flags(entry, flags);
    trace_peek_preempt_count(entry, pc);

    trace_rollback(entry);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    int syscall_num = regs->ax;
    struct ftrace_event_file *file = id_to_event_file(syscall_num);
    struct trace_entry *entry;
    unsigned long flags;

    if (!file || !ftrace_event_enabled(file))
        return;

    flags = preempt_count();
    raw_local_irq_save(flags);

    entry = ftrace_buffer_reserve(data, file->event_call->event.type);
    if (!entry)
        goto out;

    entry->type = file->event_call->event.type;
    entry->vcpu = smp_processor_id();
    entry->pid = current->pid;
    entry->ts = ftrace_now(file->system->system);

    syscall_metadata_t *meta = get_syscall_metadata(syscall_num);
    if (meta) {
        entry->syscall.id = syscall_num;
        for (int i = 0; i < meta->arg_cnt; i++) {
            entry->syscall.args[i] = regs->di + i;
        }
    }

    ftrace_buffer_commit(data, entry);

out:
    raw_local_irq_restore(flags);
}
